class Solution{	
	public:
		string longestCommonPrefix(vector<string>& str){
            string answer = "";

            int n = str.size(); // string array length
            sort(str.begin(), str.end()); // sorting the array of strings

            // if common prefix is at first and and last string then its bound to be in between
            string first = str[0];
            string last = str[n - 1];

            for(int i = 0; i<(min(first.length(), last.length())); i++){
                if(first[i]!=last[i]){
                    break;
                }
                answer += first[i];
            }
        return answer;

		}
};
